(function () {
  // ── shared helpers (SVG, tweening) ─────────────────────────────────────────
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.getElementById("scene");
  var labelEl = document.getElementById("step-label");
  var captionEl = document.getElementById("caption");

  function el(name, attrs, parent) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    if (parent) parent.appendChild(node);
    return node;
  }
  function txt(parent, x, y, cls, str, anchor) {
    var t = el("text", { x: x, y: y, class: cls }, parent);
    if (anchor) t.setAttribute("text-anchor", anchor);
    t.textContent = str;
    return t;
  }
  function show(node, on) {
    node.setAttribute("opacity", on ? "1" : "0");
  }
  function place(node, x, y) {
    node.style.transform = "translate(" + x + "px," + y + "px)";
  }
  function setLine(node, x1, y1, x2, y2) {
    node.setAttribute("x1", x1);
    node.setAttribute("y1", y1);
    node.setAttribute("x2", x2);
    node.setAttribute("y2", y2);
  }
  function lerp(a, b, e) {
    return a + (b - a) * e;
  }
  function round1(v) {
    return (Math.round(v * 10) / 10).toFixed(1);
  }

  // Eased animation. fn(e) is called with e from 0 to 1. Without
  // requestAnimationFrame (or with ms = 0) it jumps straight to fn(1).
  var animTokens = {};
  function anim(key, ms, fn) {
    var token = (animTokens[key] || 0) + 1;
    animTokens[key] = token;
    if (typeof requestAnimationFrame !== "function" || ms <= 0) {
      fn(1);
      return;
    }
    var start = null;
    function frame(now) {
      if (animTokens[key] !== token) return;
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / ms);
      var e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      fn(e);
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  // Arrowheads, one marker per colour.
  var COLORS = { g: "#1DB584", y: "#E2B44A", p: "#F472B6", b: "#38BDF8", w: "#c9dccf", r: "#F87171" };
  var defs = el("defs", {}, svg);
  Object.keys(COLORS).forEach(function (k) {
    var m = el("marker", { id: "ah-" + k, viewBox: "0 0 10 10", refX: 9, refY: 5, markerUnits: "userSpaceOnUse", markerWidth: 13, markerHeight: 13, orient: "auto" }, defs);
    el("path", { d: "M0 0 L10 5 L0 10 Z", fill: COLORS[k] }, m);
  });
  function arrow(parent, colorKey, width) {
    return el("line", { x1: 0, y1: 0, x2: 0, y2: 0, stroke: COLORS[colorKey], "stroke-width": width || 3, "marker-end": "url(#ah-" + colorKey + ")", "stroke-linecap": "round" }, parent);
  }
  function polygon(parent, cls) {
    return el("polygon", { points: "", class: cls }, parent);
  }
  function setPoly(node, pts) {
    node.setAttribute("points", pts.map(function (p) { return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" "));
  }
  function lerpPts(a, b, e) {
    return a.map(function (p, i) { return [lerp(p[0], b[i][0], e), lerp(p[1], b[i][1], e)]; });
  }
  // Maps maths coordinates (x right, y up) to screen pixels.
  function makePlane(cx, cy, s) {
    return {
      x: function (v) { return cx + s * v; },
      y: function (v) { return cy - s * v; },
      pt: function (p) { return [cx + s * p[0], cy - s * p[1]]; },
      s: s, cx: cx, cy: cy
    };
  }
  function axes(parent, plane, xr, yr) {
    el("line", { x1: plane.x(-xr), y1: plane.y(0), x2: plane.x(xr), y2: plane.y(0), class: "axis" }, parent);
    el("line", { x1: plane.x(0), y1: plane.y(-yr), x2: plane.x(0), y2: plane.y(yr), class: "axis" }, parent);
  }

  // ── Module 3 helpers: graphs, curves, contour plane ───────────────────────
  // makeGraph maps maths values to pixels with separate x and y scales.
  function makeGraph(ox, oy, sx, sy) {
    return {
      ox: ox, oy: oy, sx: sx, sy: sy,
      x: function (v) { return ox + sx * v; },
      y: function (v) { return oy - sy * v; }
    };
  }
  function curveD(g, f, a, b, n) {
    var d = "";
    for (var i = 0; i <= n; i++) {
      var v = a + ((b - a) * i) / n;
      d += (i ? " L " : "M ") + g.x(v).toFixed(1) + " " + g.y(f(v)).toFixed(1);
    }
    return d;
  }
  function setD(node, d) {
    node.setAttribute("d", d);
  }
  function fmt(v, n) {
    return (Math.round(v * 100000) / 100000).toFixed(n === undefined ? 1 : n);
  }
  function drawAxes(parent, g, xmax, ymax, xticks, yticks) {
    el("line", { x1: g.x(0), y1: g.y(0), x2: g.x(xmax), y2: g.y(0), class: "axis" }, parent);
    el("line", { x1: g.x(0), y1: g.y(0), x2: g.x(0), y2: g.y(ymax), class: "axis" }, parent);
    (xticks || []).forEach(function (t) { txt(parent, g.x(t), g.y(0) + 15, "tick", String(t), "middle"); });
    (yticks || []).forEach(function (t) { txt(parent, g.x(0) - 7, g.y(t) + 4, "tick", String(t), "end"); });
  }
  function card(parent, x, y, w, h, cls) {
    return el("rect", { x: x, y: y, width: w, height: h, rx: 10, class: cls || "fillG" }, parent);
  }
  function ring(parent, cx, cy, rx, ry, cls) {
    return el("ellipse", { cx: cx, cy: cy, rx: rx, ry: ry, fill: "none", class: cls || "contour" }, parent);
  }
  function clipTo(id, x, y, w, h) {
    var c = el("clipPath", { id: id }, defs);
    el("rect", { x: x, y: y, width: w, height: h }, c);
  }

  var EXPLAIN = {"nonlinear-function":{"h":"WHAT YOU ARE LOOKING AT","t":"Our loss **L(w) = (w − 3)²** is a curve, not a straight line. Curves are harder to work with than lines, so we look for an **easy stand-in**."},"choose-point":{"h":"CHOOSE THE POINT WE ARE STANDING AT","t":"Say the model is at **w = 1**, where the loss is **L(1) = 4**. We want to predict the loss for weights **near this point**."},"tangent-line":{"h":"DRAW THE TANGENT LINE","t":"At w = 1 the slope is **−4**. The tangent line through this point is **4 − 4h**, where h is how far we step from w = 1. Close to the point, the curve and this line almost coincide."},"nearby-point":{"h":"LOOK AT A NEARBY POINT","t":"Step to **w = 1.5**, so **h = 0.5**. The curve sits at **2.25**, while the line sits at **2.0**. They are close but not the same."},"approximation":{"h":"THE APPROXIMATION AND ITS ERROR","t":"Prediction from the line: **4 − 4 × 0.5 = 2.0**. The true loss is **2.25**. The gap, **0.25**, is the **approximation error**."},"error-grows":{"h":"THE ERROR GROWS WITH DISTANCE","t":"Step further and the curve bends away from the line. The error is **h × h**: **0.25 at h = 0.5, 1 at h = 1, and 4 at h = 2**, where the line even predicts a negative loss."},"ml-connection":{"h":"TAKEAWAY","t":"**New loss ≈ old loss + slope × change in w.** This prediction is reliable for **small steps only**, which is why training uses small steps."}};
  // ── scene ──
  var steps = [
    { id: "nonlinear-function", label: "A curved loss", caption: "Our loss L(w) = (w − 3)² is a curve, not a straight line. Curves are harder to work with than lines, so we look for an easy stand-in." },
    { id: "choose-point", label: "Choose the point we are standing at", caption: "Say the model is at w = 1, where the loss is L(1) = 4. We want to predict the loss for weights near this point." },
    { id: "tangent-line", label: "Draw the tangent line", caption: "At w = 1 the slope is −4. The tangent line through this point is 4 − 4h, where h is how far we step from w = 1. Close to the point, the curve and this line almost coincide." },
    { id: "nearby-point", label: "Look at a nearby point", caption: "Step to w = 1.5, so h = 0.5. The curve sits at 2.25, while the line sits at 2.0. They are close but not the same." },
    { id: "approximation", label: "The approximation and its error", caption: "Prediction from the line: 4 − 4 × 0.5 = 2.0. The true loss is 2.25. The gap, 0.25, is the approximation error." },
    { id: "error-grows", label: "The error grows with distance", caption: "Step further and the curve bends away from the line. The error is h × h: 0.25 at h = 0.5, 1 at h = 1, and 4 at h = 2, where the line even predicts a negative loss." },
    { id: "ml-connection", label: "Why training takes small steps", caption: "new loss ≈ old loss + slope × change in w. This prediction is reliable for small steps only, which is why training uses small steps." }
  ];

  function L(w) { return (w - 3) * (w - 3); }
  function line(w) { return 4 - 4 * (w - 1); }
  var g = makeGraph(50, 262, 58, 21);
  drawAxes(svg, g, 6.3, 9.8, [0, 1, 2, 3, 4, 5, 6], [0, 3, 6, 9]);
  txt(svg, g.x(6.3), g.y(0) + 15, "note", "weight w", "end");
  txt(svg, g.x(0) + 8, g.y(9.8) - 2, "note", "loss", "start");

  var band = el("rect", { x: g.x(0.55), y: g.y(9.6), width: g.x(1.45) - g.x(0.55), height: g.y(0) - g.y(9.6), fill: "rgba(29,181,132,0.16)", stroke: "none" }, svg);
  var bandLbl = txt(svg, g.x(0.55), g.y(9.6) - 4, "lbl lbl-g", "small step: reliable", "start");
  var farLbl = txt(svg, g.x(4.0), g.y(6.2), "lbl lbl-r", "big step: the line is off", "middle");

  el("path", { class: "curve", d: curveD(g, L, 0, 6, 60) }, svg);
  var tan = el("line", { stroke: "#e2b44a", "stroke-width": 3, "stroke-linecap": "round" }, svg);
  setLine(tan, g.x(0.2), g.y(line(0.2)), g.x(2.9), g.y(line(2.9)));
  var tanLbl = txt(svg, g.x(0.25), g.y(line(0.25)) - 10, "lbl lbl-y", "tangent: 4 − 4h", "start");
  var guideV = el("line", { class: "dash", stroke: "#c9dccf", "stroke-width": 1.5 }, svg);
  var guideH = el("line", { class: "dash", stroke: "#c9dccf", "stroke-width": 1.5 }, svg);
  setLine(guideV, g.x(1), g.y(4), g.x(1), g.y(0));
  setLine(guideH, g.x(1), g.y(4), g.x(0), g.y(4));
  var pt = el("circle", { cx: g.x(1), cy: g.y(4), r: 7, fill: "#e2b44a", stroke: "#071510", "stroke-width": 2 }, svg);
  var ptLbl = txt(svg, g.x(1) + 12, g.y(4) - 12, "lbl lbl-y", "a = 1, L = 4", "start");
  var curveP = el("circle", { r: 6, fill: "#38bdf8", stroke: "#071510", "stroke-width": 2 }, svg);
  var lineP = el("circle", { r: 6, fill: "#e2b44a", stroke: "#071510", "stroke-width": 2 }, svg);
  var gap = el("line", { stroke: "#f87171", "stroke-width": 4, "stroke-linecap": "round" }, svg);
  var gapLbl = txt(svg, 0, 0, "lbl lbl-r", "", "start");
  var lblCurve = txt(svg, 0, 0, "lbl lbl-b", "", "start");
  var lblLine = txt(svg, 0, 0, "lbl lbl-y", "", "end");

  var panel = el("g", {}, svg);
  card(panel, 410, 30, 215, 128, "fillG");
  var p1 = txt(panel, 517, 56, "note", "", "middle");
  var p2 = txt(panel, 517, 84, "mono", "", "middle");
  var p3 = txt(panel, 517, 110, "mono", "", "middle");
  var p4 = txt(panel, 517, 142, "big", "", "middle");

  function setGap(h) {
    var w = 1 + h;
    var cy = g.y(L(w)), ly = g.y(line(w));
    curveP.setAttribute("cx", g.x(w)); curveP.setAttribute("cy", cy);
    lineP.setAttribute("cx", g.x(w)); lineP.setAttribute("cy", ly);
    setLine(gap, g.x(w), cy, g.x(w), ly);
    gapLbl.setAttribute("x", g.x(w) + 10); gapLbl.setAttribute("y", (cy + ly) / 2 + 4);
    gapLbl.textContent = "error " + fmt(h * h, 2);
    lblCurve.setAttribute("x", g.x(w) + 10); lblCurve.setAttribute("y", cy + (cy < ly ? -10 : 18));
    lblCurve.textContent = "truth " + fmt(L(w), 2);
    lblLine.setAttribute("x", g.x(w) - 10); lblLine.setAttribute("y", ly + 4);
    lblLine.textContent = "line " + fmt(line(w), 2);
    p1.textContent = "step h = " + fmt(h, 2);
    p2.textContent = "line:  4 − 4×" + fmt(h, 2) + " = " + fmt(line(w), 2);
    p3.textContent = "truth: L(" + fmt(w, 2) + ") = " + fmt(L(w), 2);
    p4.textContent = "error = " + fmt(h * h, 2);
  }

  function render(index, id) {
    var past = id !== "nonlinear-function" && id !== "choose-point";
    show(band, id === "ml-connection");
    show(bandLbl, id === "ml-connection");
    show(farLbl, id === "ml-connection");
    show(guideV, id === "choose-point");
    show(guideH, id === "choose-point");
    show(pt, id !== "nonlinear-function");
    show(ptLbl, id === "choose-point" || id === "tangent-line");
    show(tan, past);
    show(tanLbl, id === "tangent-line");
    var gapOn = id === "nearby-point" || id === "approximation" || id === "error-grows";
    show(curveP, gapOn); show(lineP, gapOn); show(gap, gapOn); show(gapLbl, gapOn);
    show(lblCurve, gapOn); show(lblLine, gapOn);
    show(panel, id !== "nonlinear-function" && id !== "choose-point");
    p1.textContent = ""; p2.textContent = ""; p3.textContent = ""; p4.textContent = "";

    if (id === "tangent-line") {
      p1.textContent = "at w = 1";
      p2.textContent = "L(1) = 4";
      p3.textContent = "slope = −4";
    } else if (id === "nearby-point" || id === "approximation") {
      setGap(0.5);
      if (id === "nearby-point") { p1.textContent = "nearby point"; p2.textContent = "w = 1.5"; p3.textContent = "h = 0.5"; p4.textContent = ""; }
    } else if (id === "error-grows") {
      anim("h", 2600, function (e) { setGap(0.5 + 1.5 * e); });
    } else if (id === "ml-connection") {
      p1.textContent = "a step of Δw changes the loss by about";
      p2.textContent = "slope × Δw";
      p3.textContent = "keep Δw small";
    }
  }


  // ── shared runtime: stepping, explanation panel, educational autoplay pacing, bridge ──
  var current = 0;
  var explainHeadEl = document.getElementById("explain-h");

  // **bold** markers in an explanation become <strong> nodes (built with DOM calls, never innerHTML).
  function setRich(node, str) {
    node.textContent = "";
    var parts = String(str).split("**");
    for (var i = 0; i < parts.length; i++) {
      if (parts[i] === "") continue;
      var seg = document.createElement(i % 2 ? "strong" : "span");
      seg.textContent = parts[i];
      node.appendChild(seg);
    }
  }

  function explanationFor(index) {
    var ex = (typeof EXPLAIN === "object" && EXPLAIN) ? EXPLAIN[steps[index].id] : null;
    return ex || { h: "WHAT IS HAPPENING", t: steps[index].caption };
  }

  // Autoplay pace: 4.5 to 10.5 seconds per step, longer for longer explanations, so a learner can read.
  function stepMs(index) {
    var words = String(explanationFor(index).t).replace(/\*\*/g, "").split(/\s+/).length;
    return Math.max(4500, Math.min(10500, Math.round(3800 + words * 165)));
  }

  function renderStep(index) {
    var ex = explanationFor(index);
    labelEl.textContent = steps[index].label;
    if (explainHeadEl) explainHeadEl.textContent = ex.h;
    setRich(captionEl, ex.t);
    render(index, steps[index].id);
  }

  function goTo(index) {
    if (index < 0 || index >= steps.length) return;
    current = index;
    renderStep(current);
    if (window.ReagvisBridge) window.ReagvisBridge.stepChanged(steps[current].id);
  }

  renderStep(current);

  // Autoplay: exactly one timer, one step per tick, stops on the final step.
  // PLAY on the final step restarts from the first step and plays again.
  var timer = null;

  function stopAuto() {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function scheduleNext() {
    timer = setTimeout(function () {
      timer = null;
      if (current >= steps.length - 1) return;
      goTo(current + 1);
      if (current < steps.length - 1) scheduleNext();
    }, stepMs(current));
  }

  function startAuto() {
    if (timer !== null) return;
    if (current >= steps.length - 1) goTo(0);
    scheduleNext();
  }

  window.addEventListener("pagehide", stopAuto);

  window.ReagvisAnimation = {
    stepDuration: stepMs,
    onCommand: function (type, stepId) {
      if (type === "PLAY") startAuto();
      else if (type === "PAUSE") stopAuto();
      else if (type === "NEXT") { stopAuto(); goTo(current + 1); }
      else if (type === "PREVIOUS") { stopAuto(); goTo(current - 1); }
      else if (type === "RESET") { stopAuto(); goTo(0); }
      else if (type === "GOTO_STEP") {
        stopAuto();
        for (var i = 0; i < steps.length; i++) {
          if (steps[i].id === stepId) { goTo(i); break; }
        }
      }
    },
  };

  if (window.ReagvisBridge) {
    window.ReagvisBridge.ready();
    window.ReagvisBridge.stepChanged(steps[current].id);
  }
})();

