    print(h, prediction, loss(1 + h), loss(1 + h) - prediction)
# 0.5 2.0 2.25 0.25 / 1.0 0.0 1.0 1.0 / 2.0 -4.0 0.0 4.0

def loss(w):
    return (w - 3) ** 2

def slope(w):
    return 2 * (w - 3)

w, change = 1.0, 0.1
print(loss(w) + slope(w) * change, loss(w + change))   # 3.6 3.61 (close for a small step)
